def ab_test_probability_beta(alpha_a=None, beta_a=None, alpha_b=None, beta_b=None):
    """Bayesian A/B test: probability that A beats B. P(p_A > p_B) for independent Beta posteriors of two success probabilities (alpha_b a whole number, as after a uniform or any integer-parameter prior).
    Formula: P(p_B > p_A) = \\sum_{i=0}^{\\alpha_B - 1}\\frac{B(\\alpha_A + i,\\ \\beta_A + \\beta_B)}{(\\beta_B + i)\\,B(1 + i,\\ \\beta_B)\\,B(\\alpha_A, \\beta_A)}
    Inputs:
        alpha_a: posterior alpha of A
        beta_a: posterior beta of A
        alpha_b: posterior alpha of B (whole number)
        beta_b: posterior beta of B
    Outputs: prob_a_greater (P(p_A > p_B)), prob_b_greater (P(p_B > p_A))
    See also: help("ab_test_probability_beta")
    """
    given = {k: v for k, v in dict(alpha_a=alpha_a, beta_a=beta_a, alpha_b=alpha_b, beta_b=beta_b).items() if v is not None}
    return _P.solve("ab_test_probability_beta", **given)

def bayes_action_minimum_expected_loss(losses=None, probabilities=None):
    """Bayes action: minimum posterior expected loss. Posterior expected loss of each action from a loss matrix and (posterior) state probabilities; the Bayes action minimizes it.
    Formula: \\rho(a) = \\sum_s P(s\\mid x)\\,L(a,s),\\quad a^* = \\arg\\min_a \\rho(a)
    Inputs:
        losses: loss matrix: one row per action, one column per state
        probabilities: posterior state probabilities (sum to 1)
    Outputs: expected_losses (expected loss of each action), bayes_action (action with least expected loss), bayes_risk (its expected loss)
    See also: help("bayes_action_minimum_expected_loss")
    """
    given = {k: v for k, v in dict(losses=losses, probabilities=probabilities).items() if v is not None}
    return _P.solve("bayes_action_minimum_expected_loss", **given)

def bayes_factor_binomial_simple(successes=None, trials=None, p0=None, p1=None):
    """Bayes factor for two simple binomial hypotheses. Bayes factor BF10 for H1: p = p1 against H0: p = p0 after k successes in n trials, its log10 and the posterior probability of H1 with equal prior odds.
    Formula: BF_{10} = \\left(\\frac{p_1}{p_0}\\right)^{k}\\left(\\frac{1-p_1}{1-p_0}\\right)^{n-k}
    Inputs:
        successes: successes k
        trials: trials n (>= 1)
        p0: success probability under H0
        p1: success probability under H1
    Outputs: bf10 (Bayes factor H1 : H0), log10_bf10 (log10 of BF10), posterior_h1 (P(H1 | data) with prior odds 1)
    See also: help("bayes_factor_binomial_simple")
    """
    given = {k: v for k, v in dict(successes=successes, trials=trials, p0=p0, p1=p1).items() if v is not None}
    return _P.solve("bayes_factor_binomial_simple", **given)

