def bayes_theorem(p_a=None, p_b_given_a=None, p_b_given_not_a=None):
    """Bayes' theorem for an event and its complement. The posterior probability P(A|B) from the prior P(A) and the likelihoods P(B|A) and P(B|not A).
    Formula: P(A\\mid B) = \\frac{P(B\\mid A)\\,P(A)}{P(B\\mid A)\\,P(A) + P(B\\mid \\neg A)\\,(1 - P(A))}
    Inputs:
        p_a: prior probability P(A)
        p_b_given_a: likelihood P(B|A)
        p_b_given_not_a: likelihood P(B|not A)
    Outputs: p_a_given_b (posterior probability P(A|B)), p_b (total probability P(B)), p_not_a_given_b (P(not A|B) = 1 - P(A|B))
    See also: help("bayes_theorem")
    """
    given = {k: v for k, v in dict(p_a=p_a, p_b_given_a=p_b_given_a, p_b_given_not_a=p_b_given_not_a).items() if v is not None}
    return _P.solve("bayes_theorem", **given)

